# ---- scan rotations
import itertools
def build(a1,a2,a3,h=2.25):
    f1=place(chain_pos[0], np.array([-1.0,0,0]), np.array([0,np.sin(a1),np.cos(a1)]))
    f2=place(chain_pos[5], np.array([1.0,0,0]), np.array([0,np.sin(a2),np.cos(a2)]))
    f3=place(mid+np.array([0,h,0]), np.array([0,1.0,0]), np.array([np.cos(a3),0,np.sin(a3)]))
    return [f1,f2,f3]
def score(fr):
    allP=[chain_pos[1:5]]+[np.delete(Z,Cl,axis=0) for Z in fr]
    m=9
    for i in range(len(allP)):
        for j in range(i+1,len(allP)):
            D=np.linalg.norm(allP[i][:,None]-allP[j][None],axis=2)
            m=min(m,D.min())
    return m
best=(0,None)
angs=np.linspace(0,np.pi,12,endpoint=False)
for a1,a2,a3 in itertools.product(angs,angs,angs):
    s=score(build(a1,a2,a3))
    if s>best[0]: best=(s,(a1,a2,a3))
print("best",best)
fr=build(*best[1])
out=[]
for s,p in zip([c[0] for c in chain],chain_pos):
    if s!="Au": out.append((s,p))
for Z in fr:
    for i,(s,p) in enumerate(zip(sym,Z)):
        if i==Cl: continue
        out.append((s,p))
with open("init.xyz","w") as f:
    f.write(f"{len(out)}\ntrinuclear Au cation\n")
    for s,p in out: f.write(f"{s} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
